export function expiringSoon(wallet: Wallet, day: number, within: number): number {
  if (within <= 0) return 0;
  let total = 0;
  for (const batch of wallet.batches) {
    const goodOnDay = batch.bought <= day && day < batch.bought + TOKEN_LIFE_DAYS;
    const deadLater = day + within >= batch.bought + TOKEN_LIFE_DAYS;
    if (goodOnDay && deadLater) total += batch.left;
  }
  return total;
}
